d as (select n, substr(x, 1, 1) e, substr(x, 2, 1) g, substr(x, 3, 1) c, sum(pg_temp.b36(substr(x, 4))) over (order by n) as prefixo from r),
emp as (select nome, (n - 1)::int i from unnest(array['A2 Transportes','Alfa Rodobus','Alfa Rodobus SPE','Gato Preto','Gato Preto A1','Metrópole AE Carvalho','Metrópole Expandir (Brás)','Metrópole Iguatemi','Metrópole Imperador','Metrópole Itaim','Metrópole M''Boi Mirim','Metrópole Pinedo','Norte Buss A1','Norte Buss A2','Noxxonsat','Santa Brígida','Trans União','Transunião Transportes D7','Via Sudeste','Viação Grajaú']) with ordinality as t(nome, n)),
gar as (select nome, (n - 1)::int i from unnest(array['A2 Transportes','Alfa Rodobus','Alfa Rodobus SPE','Gato Preto - Portinari','Gato Preto - Mackenzie','Norte Buss A1','Norte Buss A2','Santa Brigida','Trans União D3','Trans União D7','Via Sudeste Cursino','Via Sudeste Sapopemba','Viação Grajaú','Viação Metrópole AE Carvalho','Viação Metrópole Brás','Viação Metrópole Iguatemi','Viação Metrópole Imperador','Viação Metrópole Itaim','Viação Metrópole M''Boi Mirim','Viação Metrópole Pinedo']) with ordinality as t(nome, n)),
f as (select d.prefixo::int prefixo, emp.nome empresa, gar.nome garagem,
        case d.c when 'a' then 'mini' when 'c' then 'padron' when 'd' then 'articulado' end tecnologia,
        case d.c when 'a' then '{21}' when 'b' then '{21,22}' when 'c' then '{21,22,23}' else '{21,22,23,24,25,26}' end::smallint[] cams
      from d left join emp on emp.i = strpos('0123456789abcdefghijklmnopqrstuvwxyz', d.e) - 1
             left join gar on gar.i = strpos('0123456789abcdefghijklmnopqrstuvwxyz', d.g) - 1),
v as (insert into public.veiculos (prefixo, empresa_id, garagem_id, tecnologia)
      select f.prefixo, e.id, g.id, f.tecnologia from f left join public.empresas e on e.nome = f.empresa left join public.garagens g on g.nome = f.garagem
      on conflict (prefixo) do nothing returning id, prefixo)
select v.id, unnest(f.cams) from v join f on f.prefixo = v.prefixo
on conflict do nothing;
